import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Providers API","description":"","frontmatter":{},"headers":[],"relativePath":"api/providers.md","filePath":"api/providers.md"}'),o={name:"api/providers.md"};function d(n,e,r,c,p,l){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="providers-api" tabindex="-1">Providers API <a class="header-anchor" href="#providers-api" aria-label="Permalink to &quot;Providers API&quot;">​</a></h1><p>Provider endpoints expose installed agent CLI metadata, capabilities, diagnostics, and safe provider-specific command surfaces.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="list-providers" tabindex="-1">List Providers <a class="header-anchor" href="#list-providers" aria-label="Permalink to &quot;List Providers&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers</span></span></code></pre></div><p>Returns registered providers such as <code>claude-code</code>, <code>codex-cli</code>, and <code>copilot-cli</code>, including install status, version, capabilities, and config paths.</p><p>Capability flags are stable booleans. Unsupported provider surfaces are returned as <code>false</code>; detailed provider-specific state belongs in metadata fields such as backup policy, diagnostics, inventory, or command status.</p><h3 id="provider-status" tabindex="-1">Provider Status <a class="header-anchor" href="#provider-status" aria-label="Permalink to &quot;Provider Status&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/{provider_id}/status</span></span></code></pre></div><p>Returns status for one provider.</p><h3 id="operating-catalog-and-readiness" tabindex="-1">Operating Catalog and Readiness <a class="header-anchor" href="#operating-catalog-and-readiness" aria-label="Permalink to &quot;Operating Catalog and Readiness&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/{provider_id}/operations</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/{provider_id}/operations?team_id=1&amp;slot_id=2</span></span></code></pre></div><p>Schema version <code>1</code> keeps <code>operations</code>, <code>native_capabilities</code>, <code>native_surfaces</code> and <code>readiness</code> separate. The existing registry/status/capability responses remain unchanged. Every provider has these exact operation keys:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Claude / Codex</th><th>Copilot / OpenCode</th><th>Pi</th></tr></thead><tbody><tr><td><code>launch</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>observe_session</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>mail_identity</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>receive_work</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>report_work_status</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>approval_participation</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>workspace_association</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>resume_exact</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>interactive_terminal</code></td><td>conditional</td><td>conditional</td><td>conditional</td></tr><tr><td><code>execution_controls</code></td><td>conditional</td><td>unknown</td><td>unsupported</td></tr></tbody></table><p>Each classification includes <code>reason</code>, <code>conditions</code> and checked-in <code>evidence</code> references. Conditions retain current authenticated identity, dispatch/lease/approval, exact resume/project and native execution-control limits. Classifications describe support rather than grant authority or certify isolation.</p><p>Each <code>native_surfaces</code> entry supplies <code>state</code> (<code>available</code>, <code>unavailable</code>, <code>unknown</code>), <code>adapter_id</code>, <code>access</code> (<code>none</code>, <code>read_only</code>, <code>read_write</code>), reason and conditions. Unavailable/unknown surfaces have no adapter and no access. Available IDs must match the implemented provider/page/component registry; capability flags alone cannot create a page. Browser guards intersect this catalog with the static adapter and native capabilities before mounting, fetching or writing. Required catalog failure cannot fall back to static permissions. The exact known-provider operations GET is the read-only bootstrap exception; it does not allow mutations or arbitrary catalog-provided API paths.</p><p>Readiness separates configuration checks from credentials and session identity. Configuration uses the binary/Mail prerequisites shared with launch planning; <code>ready</code> means <strong>Configured for launch</strong>, not verified model access. Negative legacy Mail observations can represent failed probes; the check remains unknown even when missing positive evidence blocks launch. Credentials are not checked and remain unknown. The generic request never establishes a team-slot worker binding.</p><p>Optional <code>team_id</code> and <code>slot_id</code> must be paired positive integers. A scoped read validates the configured provider, exactly one authenticated member matching both team and slot, all conflicting live MCP candidates before provider selection, observed provider, heartbeat and exact non-retired pane PID/process-start evidence. Unpaired/invalid input returns 422; missing/mismatched slot context or unknown provider returns 404. Ambiguous, stale, offline or unavailable evidence cannot become a bound session. Reads use team-scoped SQL evidence and do not discover processes, claim work, launch sessions or mutate lifecycle state.</p><p><code>observed_at</code>, <code>observation_started_at</code>, <code>probe_state</code>, cache TTL, request wait and aggregate deadline expose observation limits. One singleflight snapshot worker per API process shares safe allowlisted flags across cards for 60 seconds; each request waits at most two seconds. At the 90-second observation deadline a private Linux supervisor terminates only the trusted observer-owned process group and reaps its children before snapshot completion or refresh. Cleanup time is awaited, not guaranteed to finish at exactly 90 seconds. Unsupported cleanup support, malformed observations and failures project to unknown. Local version/runtime/MCP-inventory checks perform no model calls, credential checks/refreshes or production-session launches; public responses contain no raw install status, private errors, host paths or output. The cleanup is not containment of hostile/self-detaching processes.</p><p>Reviewed schema fixtures are in <code>backend/tests/fixtures/provider-operations/v1</code> and their byte-identical frontend copy; they are separate from frozen P01 and P02 fixtures. New full-head review, hosted CI and human merge remain distinct from source/fixture acceptance.</p><h3 id="codex-doctor" tabindex="-1">Codex Doctor <a class="header-anchor" href="#codex-doctor" aria-label="Permalink to &quot;Codex Doctor&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/doctor</span></span></code></pre></div><p>Runs Codex diagnostics and returns redacted output.</p><h3 id="codex-inventory" tabindex="-1">Codex Inventory <a class="header-anchor" href="#codex-inventory" aria-label="Permalink to &quot;Codex Inventory&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/features</span></span></code></pre></div><p>Returns Codex MCP, plugin, and feature inventory. Secret-like values are redacted. MCP JSON output is parsed and redacted before any raw output is returned. Plugin text output is treated as read-only text with best-effort row parsing.</p><p>Feature inventory is parsed from <code>codex features list</code> and returns the feature name, stage, and effective enabled state. Removed and deprecated flags may still be present in raw CLI output; the frontend hides those from the main toggle list unless they already exist as explicit config overrides.</p><h3 id="codex-mcp-mutation" tabindex="-1">Codex MCP Mutation <a class="header-anchor" href="#codex-mcp-mutation" aria-label="Permalink to &quot;Codex MCP Mutation&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp/{name}</span></span></code></pre></div><p>Adds or removes Codex MCP servers through the Codex CLI with strict validation.</p><h3 id="codex-plugin-mutation" tabindex="-1">Codex Plugin Mutation <a class="header-anchor" href="#codex-plugin-mutation" aria-label="Permalink to &quot;Codex Plugin Mutation&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins/{name}</span></span></code></pre></div><p>Installs or removes Codex plugins through the Codex CLI when the installed CLI exposes safe commands. Codex plugin enable/disable remains unsupported until Codex exposes a stable safe contract.</p><h3 id="codex-config-profile-diagnostics" tabindex="-1">Codex Config/Profile Diagnostics <a class="header-anchor" href="#codex-config-profile-diagnostics" aria-label="Permalink to &quot;Codex Config/Profile Diagnostics&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/codex-config</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/codex-config/profile-diagnostics</span></span></code></pre></div><p>Returns redacted Codex config summaries, profile-file diagnostics, and active/default profile resolution. Auth, history, cache, and raw secret values are omitted or redacted.</p><h3 id="codex-usage-context-diagnostics" tabindex="-1">Codex Usage/Context Diagnostics <a class="header-anchor" href="#codex-usage-context-diagnostics" aria-label="Permalink to &quot;Codex Usage/Context Diagnostics&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/usage-context-diagnostics</span></span></code></pre></div><p>Returns diagnostics-only metadata for Codex history and model cache shape. This endpoint does not return prompt text, session ids, raw history rows, model ids, raw model cache payloads, auth data, or SQLite contents. Usage and context parity are explicitly unsupported for Codex.</p><h2 id="normalized-provider-errors" tabindex="-1">Normalized Provider Errors <a class="header-anchor" href="#normalized-provider-errors" aria-label="Permalink to &quot;Normalized Provider Errors&quot;">​</a></h2><p>Provider endpoints should surface user-actionable error states:</p><table tabindex="0"><thead><tr><th>Error code/state</th><th>Meaning</th></tr></thead><tbody><tr><td><code>unknown_provider</code></td><td>The requested provider id is not registered.</td></tr><tr><td><code>unsupported_operation</code></td><td>The provider does not support the requested capability.</td></tr><tr><td><code>unsupported_provider_operation</code></td><td>The endpoint exists, but only for another provider.</td></tr><tr><td><code>command_not_allowed</code></td><td>The requested CLI command is outside the provider whitelist.</td></tr><tr><td><code>provider_binary_missing</code></td><td>The provider CLI is not installed or not on <code>PATH</code>.</td></tr><tr><td>CLI failure</td><td>The CLI returned a non-zero exit code; stdout/stderr are redacted.</td></tr><tr><td>Parse failure</td><td>CLI output could not be parsed; raw sensitive payloads are omitted or redacted.</td></tr><tr><td>Validation failure</td><td>User input failed strict validation before any CLI command ran.</td></tr></tbody></table><p>The frontend should use provider status and these error states to disable unsupported controls instead of routing Codex users to Claude-only pages.</p>`,43)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
